UPDATE public.pages SET builder_data = jsonb_insert(builder_data, '{sections,7}', '{"id": "6ee866eb-1ea5-4e51-b4b6-f0fc4e309576", "kind": "section", "layout": {"width": 1200, "contentWidth": "boxed"}, "children": [{"id": "0756ad13-cbd5-4c31-ace9-d11771d004c3", "kind": "column", "span": {"desktop": 12}, "children": [{"id": "6b878a2d-7d6c-4cba-bd5f-03d0d75ce779", "kind": "widget", "type": "tabs", "content": {"tabs": [{"label_pl": "Bycie częścią Społeczności", "label_en": "Being part of the Community", "html_pl": "<p>Wsparcie think-tanku to również <strong>przynależność do społeczności osób</strong>, które dzielą podobne <strong>wartości</strong> i <strong>aspiracje</strong>.</p><p>Jest to okazja do uczestnictwa w budowaniu przestrzeni dla otwartej i konstruktywnej debaty, co jest kluczowe dla demokratycznych społeczeństw.</p><p>Wsparcie think-tanku to <strong>nie tylko</strong> inwestycja w jego misję, ale również w osobisty rozwój. Dzięki udziałowi w zamkniętych wydarzeniach, konferencjach i warsztatach <strong>wspierający mają możliwość nawiązania bezpośrednich relacji</strong> z ekspertami, liderami myśli oraz innymi osobami o podobnych zainteresowaniach, co może otwierać nowe drogi rozwoju zawodowego.</p>", "html_en": "<p>Supporting the think-tank also means <strong>belonging to a community of people</strong> who share similar <strong>values</strong> and <strong>aspirations</strong>.</p><p>It is an opportunity to participate in building a space for open and constructive debate, which is key for democratic societies.</p><p>Supporting the think-tank is <strong>not only</strong> an investment in its mission, but also in personal development. Through participation in closed events, conferences and workshops, <strong>supporters have the opportunity to build direct relationships</strong> with experts, thought leaders and other like-minded people, opening new professional-development paths.</p>"}, {"label_pl": "Udział w specjalnych projektach", "label_en": "Participation in special projects", "html_pl": "<p>Ekskluzywne zaproszenie na roczne spotkanie darczyńców, które oferuje wgląd w plany i strategie na przyszłość, umożliwia bezpośrednią interakcję z zarządem i ekspertami, oraz celebruje osiągnięcia think-tanku wspierane przez darczyńców.</p><p>Dla zainteresowanych <strong>istnieje możliwość uczestniczenia w badaniach</strong> i wybrane <strong>projekty badawcze</strong> jako współautorzy lub obserwatorzy, dając unikalną perspektywę za kulisami pracy think-tanku.</p>", "html_en": "<p>An exclusive invitation to the annual donor meeting, offering insight into plans and strategies for the future, enabling direct interaction with the board and experts, and celebrating the think-tank''s achievements supported by donors.</p><p>For those interested, <strong>there is a possibility to participate in research</strong> and selected <strong>research projects</strong> as co-authors or observers, providing a unique behind-the-scenes perspective of the think-tank''s work.</p>"}, {"label_pl": "Wpływ na debatę publiczną", "label_en": "Impact on public debate", "html_pl": "<p>Wspierając think-tank, masz <strong>możliwość wywierania wpływu</strong> na kierunki jego badań i analiz. Możliwość sugerowania tematów czy problemów do zbadania daje realny wpływ na kształtowanie przyszłości dyskursu publicznego i politycznego.</p><p><strong>Udział w konsultacjach i ankietach</strong> dotyczących priorytetów badawczych think-tanku, co umożliwia wpływanie na kierunki jego działalności i podnoszenie świadomości na ważne tematy.</p>", "html_en": "<p>By supporting the think-tank, you have <strong>the possibility to influence</strong> the directions of its research and analyses. The opportunity to suggest topics or issues for research gives real influence over shaping the future of public and political discourse.</p><p><strong>Participation in consultations and surveys</strong> concerning the think-tank''s research priorities, which enables you to influence the directions of its activities and raise awareness on important topics.</p>"}, {"label_pl": "Rola Ambasadora", "label_en": "Ambassador role", "html_pl": "<p><strong>Możliwość zostania ambasadorem think-tanku</strong>: Dla najbardziej zaangażowanych darczyńców, oferujemy rolę ambasadora New European Strategies, co umożliwia głębsze zaangażowanie w działalność i misję organizacji oraz reprezentowanie jej na zewnątrz.</p>", "html_en": "<p><strong>Opportunity to become a think-tank ambassador</strong>: For the most engaged donors, we offer the role of New European Strategies ambassador, enabling deeper involvement in the organisation''s activities and mission and representing it externally.</p>"}, {"label_pl": "Preferencyjne warunki", "label_en": "Preferential terms", "html_pl": "<p><strong>Zniżki na uczestnictwo</strong> w wybranych <strong>wydarzeniach</strong> organizowanych przez New European Strategies, umożliwiające dostęp do wiedzy i doświadczeń na preferencyjnych warunkach.</p>", "html_en": "<p><strong>Discounts on participation</strong> in selected <strong>events</strong> organised by New European Strategies, providing access to knowledge and experience on preferential terms.</p>"}, {"label_pl": "Indywidualne docenienie", "label_en": "Individual appreciation", "html_pl": "<p>Każdy wspierający zostaje <strong>indywidualnie wyróżniony i doceniony</strong> za swój wkład, co może przybierać formę listów gratulacyjnych, wzmianek w publikacjach czy na stronie internetowej think-tanku. To nie tylko wyraz uznania, ale również potwierdzenie Twojego zaangażowania w ważne społecznie kwestie.</p><p><strong>Otrzymasz unikalne materiały promocyjne</strong> takie jak certyfikaty czy gadżety związane z New European Strategies, stanowiące pamiątkę Twojego wsparcia.</p>", "html_en": "<p>Every supporter is <strong>individually distinguished and appreciated</strong> for their contribution, which may take the form of congratulatory letters, mentions in publications or on the think-tank''s website. This is not only an expression of appreciation, but also confirmation of your involvement in socially important issues.</p><p><strong>You will receive unique promotional materials</strong> such as certificates or gadgets related to New European Strategies, as a memento of your support.</p>"}, {"label_pl": "Wspieranie niezależnych analiz", "label_en": "Supporting independent analyses", "html_pl": "<p><strong>Przyczynianie się do niezależnej myśli:</strong> Twoje wsparcie umożliwia think-tankowi zachowanie niezależności badawczej i analitycznej, co jest kluczowe dla obiektywnej oceny i prognozowania przyszłych wyzwań.</p>", "html_en": "<p><strong>Contributing to independent thought:</strong> Your support enables the think-tank to maintain research and analytical independence, which is key for objective assessment and forecasting of future challenges.</p>"}, {"label_pl": "Zaufanie i transparentność", "label_en": "Trust and transparency", "html_pl": "<p><strong>Regularne raporty o postępach</strong> projektów finansowanych z darowizn, zapewniające przejrzystość i pokazujące realny wpływ Twojego wsparcia.</p><p>Dodatkowo, będziesz otrzymywać <strong>specjalny newsletter</strong> dedykowany dla darczyńców, zawierającego ekskluzywne informacje, analizy oraz zapowiedzi nadchodzących inicjatyw i możliwości zaangażowania.</p>", "html_en": "<p><strong>Regular progress reports</strong> on projects funded by donations, ensuring transparency and showing the real impact of your support.</p><p>Additionally, you will receive a <strong>special newsletter</strong> dedicated to donors, containing exclusive information, analyses and previews of upcoming initiatives and engagement opportunities.</p>"}]}}]}]}'::jsonb, false) WHERE id = '2d7776f2-d1ad-437e-8607-62b39c2b37a2';